CREATE TABLE IF NOT EXISTS public.lga_wards (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    state TEXT NOT NULL,
    lga TEXT NOT NULL,
    ward TEXT NOT NULL,
    latitude NUMERIC,
    longitude NUMERIC,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (state, lga, ward)
);

-- Enable RLS and add a public read policy
ALTER TABLE public.lga_wards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Enable read access for all users" ON public.lga_wards FOR SELECT USING (true);

